// xt.db.node.runtime/DEFAULT_TRANSPORT [16] 
export var DEFAULT_TRANSPORT = "xt.db.default.transport";

// xt.db.node.runtime/DEFAULT_WORKER [19] 
export var DEFAULT_WORKER = "xt.db.default.worker";

// xt.db.node.runtime/init-server [22] 
export function init_server(node,...optional){
  let options = (optional.length > 0) ? optional[0] : null;
  options = (options || {});
  if(null != options["backends"]){
    kernel_base.set_backends(node,options["backends"]);
  }
  page_proxy.install(node);
  kernel_base.init_handlers(node);
  for(let install of (null == options["init_handlers"]) ? [] : options["init_handlers"]){
    install(node);
  };
  return node;
}

// xt.db.node.runtime/init-server-proxy [33] 
export function init_server_proxy(node,...optional){
  let options = (optional.length > 0) ? optional[0] : null;
  page_proxy.install(node);
  proxy_base.init_proxy_handlers(node);
  for(let install of (null == (options || {})["init_proxy_handlers"]) ? [] : (options || {})["init_proxy_handlers"]){
    install(node);
  };
  return node;
}

// xt.db.node.runtime/sharedworker-init-kernel [46] 
export function sharedworker_init_kernel(node,transport_id,worker_id,...optional){
  let options = (optional.length > 0) ? optional[0] : null;
  init_server(node,options);
  globalThis["onconnect"] = (function (e){
    let port = e["ports"][0];
    let connection_transport_id = frame.rand_id((transport_id || DEFAULT_TRANSPORT) + ".",12);
    port.start();
    return browser_transport.boot_self(node,{
      "transport_id":connection_transport_id,
      "target":port,
      "ready":{
            "signal":"ready",
            "transport":connection_transport_id,
            "worker":worker_id || DEFAULT_WORKER
          }
    });
  });
}

