// xt.db.node.runtime/webworker-connect [176] 
export function webworker_connect(client,config,schema,lookup,source,transport_id,...optional){
  let options = (optional.length > 0) ? optional[0] : null;
  init_server_proxy(client,options);
  return browser_transport.connect_worker(client,{
    "transport_id":transport_id || DEFAULT_TRANSPORT,
    "source":source || browser_transport.webworker_source(DEFAULT_WEBWORKER_SCRIPT,{"type":"module"})
  }).then(function (conn){
    return client_base.kernel_init(client,config,schema,lookup,{});
  });
}

// xt.db.node.runtime/nodeworker-init-kernel [200] 
export function nodeworker_init_kernel(node,transport_id,worker_id,...optional){
  let options = (optional.length > 0) ? optional[0] : null;
  init_server(node,options);
  let worker = {
    "postMessage":function (data){
        parentPort.postMessage(data);
      },
    "addEventListener":function (event,listener,capture){
        if(event == "message"){
          parentPort.on("message",function (data){
            listener({"data":data});
          });
        }
      }
  };
  return browser_transport.boot_self(node,{
    "transport_id":transport_id || DEFAULT_TRANSPORT,
    "target":worker,
    "ready":{
        "signal":"ready",
        "transport":transport_id || DEFAULT_TRANSPORT,
        "worker":worker_id || DEFAULT_WORKER
      }
  });
}

